return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Прави резервне копије ваших WordPress датотека и базе података у ваше сопствено складиште — Dropbox, Google Drive, Cloudflare R2, Amazon S3 или било који S3 компатибилан бакет — враћа их у једном кораку и увози резервне копије направљене помоћу других додатака за резервне копије и миграцију.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Резервне копије','Get Pro: schedules, several storages, encryption'=>'Набавите Pro: распореди, више складишта, шифровање','Working…'=>'Ради се…','Finished'=>'Завршено','Failed'=>'Неуспешно','Cancelled'=>'Отказано','Cancel'=>'Откажи','Restore'=>'Врати','Delete'=>'Обриши','Delete this backup from your storage? This cannot be undone.'=>'Желите ли да избришете ову резервну копију из вашег складишта? Ова радња се не може опозвати.','No backups yet. Press “Back up now” to make the first one.'=>'Још увек нема резервних копија. Притисните „Направи резервну копију сада“ да бисте направили прву.','Reading your storage…'=>'Очитавање вашег складишта…','a complete backup, as opposed to an incremental oneFull backup'=>'Комплетна резервна копија','a backup holding only what changed since an earlier oneIncremental backup'=>'Инкрементална резервна копија','Encrypted'=>'Шифровано','From another site'=>'Са другог веб-места','Database'=>'База података','Files'=>'Датотеке','Uploading %1$s: %2$s%%'=>'Отпремање %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Пријавите се на Dropbox у отвореном прозору, а затим налепите код који вам Dropbox приказује:','Saved.'=>'Сачувано.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Уклонити ово одредиште из прикључка? Резервне копије које су у њему сачуване се не бришу.','Reload the page to see the restored site.'=>'Поново учитајте страницу да бисте видели враћени сајт.','Storage'=>'Складиште','Import & migrate'=>'Увези и мигрирај','Settings'=>'Подешавања','Sections'=>'Одељци','Google Drive is connected.'=>'Google Drive је повезан.','Google Drive could not be connected.'=>'Није било могуће повезати се на Google Drive.','Details'=>'Детаљи','Back up now'=>'Направите резервну копију сада','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Резервне копије иду у ваше сопствено складиште, а не на овај сервер. Прво <a href="%s">повежите своје складиште</a>.','What to back up'=>'Шта резервно копирати','Files and database'=>'Датотеке и база података','Database only'=>'Само база података','Files only'=>'Само датотеке','Note (optional)'=>'Белешка (опционо)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Сваки део се отпрема у ваше складиште и уклања са овог сервера пре него што се направи следећи, тако да резервна копија никада не заузима простор на вашем хостингу.','Your backups'=>'Ваше резервне копије','Refresh'=>'Освежи','Restore this backup'=>'Вратите ову резервну копију','Passphrase'=>'Лозинка','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Разумем да ово замењује датотеке и базу података овог веб-места онима из резервне копије. Датотеке које се не налазе у резервној копији се задржавају.','Recent activity'=>'Недавна активност','Backup'=>'Резервна копија','Restore / import'=>'Врати / увези','Running'=>'Покренуто','Your storage'=>'Ваш простор за складиштење' . "\0" . 'Ваша одредишта за складиштење' . "\0" . 'Ваша одредишта за складиштење','No storage yet. Choose where your backups go below.'=>'Још увек нема складишта. Изаберите у наставку где иду ваше резервне копије.','Ready'=>'Спремно','Not connected'=>'Није повезано','Connect'=>'Повежи се','Test'=>'Тест','Edit'=>'Уреди','Remove'=>'Уклони','Add storage'=>'Додајте складиште','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Резервне копије иду на једно одредиште за складиштење. Да бисте користили друго, уредите или уклоните оно изнад.','Kind of storage'=>'Врста складишта','Name (for you)'=>'Назив (за вас)','Provider'=>'Провајдер','Cloudflare account id'=>'ИД Cloudflare налога','Endpoint address'=>'Адреса крајње тачке','Region'=>'Регион','Bucket'=>'Бакет','Access key id'=>'ИД приступног кључа','Secret access key'=>'Тајни приступни кључ','Leave empty to keep the saved key'=>'Оставите празно да бисте задржали сачувани кључ','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'За Cloudflare R2: на Cloudflare контролној табли отворите R2, направите складиште (bucket), затим „Manage R2 API tokens“ → направите жетон са дозволама Object Read & Write за то складиште и овде копирајте ID приступног кључа (access key id) и тајни кључ.','Dropbox app key'=>'Кључ Dropbox апликације','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Направите апликацију на dropbox.com/developers/apps (Scoped access, App folder) са дозволама files.content.read, files.content.write и files.metadata.read, и овде копирајте њен App key. Сачувајте, па притисните Повежи се.','OAuth client id'=>'ИД OAuth клијента','OAuth client secret'=>'Тајни кључ OAuth клијента','Leave empty to keep the saved secret'=>'Оставите празно да бисте задржали сачувану тајну','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'У Google Cloud Console омогућите Google Drive API, а затим направите OAuth клијент типа „Web application“ са овом адресом као овлашћеним URI-јем за преусмеравање:','Save, then press Connect. The plugin only sees the files it creates.'=>'Сачувајте, па притисните Повежи се. Прикључак види само датотеке које сам направи.','Folder inside the storage (optional)'=>'Фасцикла унутар складишта (опционо)','Save storage'=>'Уштедите простор за складиштење','Import a backup from another plugin or host'=>'Увезите резервну копију из другог прикључка или са другог хостинга','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Увезите веб-место из резервне копије коју су направили UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate или било које zip/tar архиве WordPress веб-места са његовим .sql извозом. Садржај иде у wp-content, а база података замењује базу овог веб-места; адресе се аутоматски мењају у адресе овог веб-места.','Upload from your computer'=>'Отпремите са свог рачунара','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Изаберите сваку датотеку резервне копије одједном (UpdraftPlus прави неколико). Велике датотеке се шаљу у малим деловима, тако да се ограничење отпремања вашег хостинга не примењује.','Or from links (Google Drive, Dropbox or any download address)'=>'Или са веза (Google Drive, Dropbox или било која адреса за преузимање)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Једна веза по реду. За Google Drive и Dropbox, поделите датотеку са „сваким ко има везу“ и налепите ту везу; након тога поново искључите дељење.','Or a file already on this server'=>'Или датотека која се већ налази на овом серверу','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Отпремите архиве путем FTP-а или менаџера датотека вашег хостинга у %s и поново учитајте ову страницу.','Or a deploy code from another site'=>'Или код за постављање са другог веб-места','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Ако вам је други сајт дао код за примену Zinn® Backups-а, налепите га овде да бисте копирали ту резервну копију на овај сајт без дељења њених кључева за складиштење. Код ради неколико сати; третирајте га као лозинку.','Passphrase (only if that backup is encrypted)'=>'Лозинка (само ако је та резервна копија шифрована)','Import'=>'Увези','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Разумем да увоз замењује садржај и базу података овог веб-места. Након тога се пријавите на налогом са увезеног веб-места.','Moving to Zinn® hosting?'=>'Прелазите на Zinn® хостинг?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® може пренети ваш сајт са вашег старог хостинга. Ако вам стари хостинг не пружа приступ преко FTP-а, SSH-а или контролног панела, инсталирајте Zinn® Migrate на старом сајту; он прави једну архиву коју можете увести овде или предати сервису Zinn®.','What goes into a backup'=>'Шта улази у резервну копију','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Укључите сопствене датотеке система WordPress (wp-admin, wp-includes). Обично није потребно: WordPress се увек може поново инсталирати.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Такође изоставите ове фасцикле или датотеке (једна по реду, у односу на WordPress фасциклу)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Увек изостављено: кеш меморије, привремени простор за ажурирање и сопствене архивске фасцикле других додатака за резервне копије:','Size of each part (MB)'=>'Величина сваког дела (MB)','Save settings'=>'Сачувај подешавања','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Део резервне копије није могао бити отворен за уписивање. Проверите да ли у wp-content фасцикли има слободног простора.','A backup part could not be written. Check that wp-content has free space.'=>'Део резервне копије није могао бити уписан. Проверите да ли у wp-content има слободног простора.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Прво повежите одредиште за складиштење на картици Storage: резервне копије се чувају у вашем сопственом складишту, а не на овом серверу.','Multisite networks are not supported yet.'=>'Мреже сајтова (мултисајт) још увек нису подржане.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP овог сервера нема додатак ZipArchive. Затражите од свог хостинга да га омогући.','Starting'=>'Покретање','Listing files'=>'Листање датотека','Backing up the database'=>'Прављење резервне копије базе података','Packing files'=>'Паковање датотека','Uploading to your storage'=>'Отпремање у ваше складиште','Finishing'=>'Завршавање','The backup reached an unknown stage.'=>'Резервна копија је достигла непознату фазу.','Backup %s started.'=>'Резервно копирање за %s је почело.','Found %1$s files (%2$s).'=>'Пронађено је %1$s датотека (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'База података: %1$d табела, %2$s редова, %3$s компресовано.','Backup complete: %1$s stored in %2$d destination.'=>'Резервна копија је завршена: %1$s је сачувано на %2$d одредишту.' . "\0" . 'Резервна копија је завршена: %1$s је сачувано на %2$d одредишта.' . "\0" . 'Резервна копија је завршена: %1$s је сачувано на %2$d одредишта.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Неки делови који су већ отпремљени нису могли бити уклоњени из вашег складишта; они се налазе у фасцикли непотпуне резервне копије и никада се не нуде за враћање.','A storage destination was removed while the backup was running.'=>'Одредиште за складиштење је уклоњено током прављења резервне копије.','That is not a backup folder.'=>'То није фасцикла резервне копије.','That storage destination is no longer saved on this site.'=>'То одредиште за складиштење више није сачувано на овом веб-месту.','Later incremental backups are built on this one. Delete those first.'=>'Касније инкременталне резервне копије су изграђене на овој. Прво обришите њих.','This file is not an encrypted Zinn® Backups file.'=>'Ова датотека није шифрована Zinn® Backups датотека.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Резервна копија није могла бити дешифрована: лозинка је погрешна или је датотека оштећена.','The encrypted backup file is incomplete.'=>'Шифрована датотека резервне копије је непотпуна.','The database file could not be written. Check that wp-content has free space.'=>'Датотека базе података се није могла уписати. Проверите да ли у wp-content има слободног простора.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'То није код за отпремање. Код за отпремање почиње са zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Тај код за постављање је оштећен. Копирајте га поново са другог веб-места.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Код за отпремање је истекао или је његова резервна копија избрисана. Направите нови код на другом месту.','That deploy code does not point at a Zinn® Backups backup.'=>'Тај код за отпремање не показује на резервну копију Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Код за постављање је истекао. Направите нови код на другом веб-месту.','The server stopped honouring partial downloads. Start the import again.'=>'Сервер је престао да подржава делимична преузимања. Покрените увоз поново.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Веза је отворила веб-страницу уместо датотеке. За Google Drive и Dropbox, поделите датотеку са опцијом „свако ко има везу“ и налепите ту везу.','The link answered with HTTP %d.'=>'Веза је одговорила са HTTP %d.','The file list could not be written.'=>'Није било могуће уписати списак датотека.','The storage service could not be reached: %s'=>'Није било могуће приступити услузи складиштења: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s је одговорио са HTTP %2$d: %3$s','no details given'=>'Детаљи нису наведени','You are not allowed to manage backups.'=>'Није вам дозвољено да управљате резервним копијама.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Означите поље да потврдите да враћање резервне копије замењује датотеке и базу података овог веб-места.','Save the destination first.'=>'Прво сачувајте одредиште.','Connected: a test file was written and removed.'=>'Повезано: тест датотека је уписана и уклоњена.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Прво унесите кључ апликације ваше Dropbox апликације (погледајте кораке поред обрасца).','This kind of storage does not sign in.'=>'Ова врста складишта се не пријављује.','The sign-in expired. Press Connect again.'=>'Пријављивање је истекло. Притисните Повежи поново.','Dropbox is connected.'=>'Dropbox је повезан.','Settings saved.'=>'Подешавања су сачувана.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'У току је друго прављење резервне копије, враћање или увоз. Сачекајте да се заврши или га откажите.','The upload was not started properly. Start again.'=>'Отпремање није почело правилно. Почните поново.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Део није стигао. Ваш сервер можда ограничава величину отпремања; покушајте поново.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Означите поље да потврдите да увоз замењује садржај и базу података овог веб-места.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Изаберите архиву за увоз: отпремите је, налепите везу или изаберите неку из фасцикле за увоз.','Hosting customer? Get %1$d%% off %2$s'=>'Корисник хостинга? Остварите %1$d%% попуста на %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Као корисник Zinn Digital® хостинга добијате лични код за %d%% попуста на своју прву уплату. Обнове су по редовној цени.','Get my %d%% code and go to checkout'=>'Преузмите мој код за %d%% и идите на плаћање','Sorry, you are not allowed to do that.'=>'Жао нам је, немате дозволу да то урадите.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Овај попуст је намењен корисницима са плаћеним хостинг пакетом у добром статусу. Бесплатне пробе не испуњавају услове.','You have already used your hosting-customer discount for this plugin.'=>'Већ сте искористили свој попуст за кориснике хостинга за овај додатак.','We could not get your code just now. Please try again in a few minutes.'=>'Управо нисмо успели да добијемо Ваш код. Молимо покушајте поново за неколико минута.','Reading the backup'=>'Читање резервне копије','Downloading the archive'=>'Преузимање архиве','Recognising the archive'=>'Препознавање архиве','Restoring files'=>'Враћање датотека','Downloading the database'=>'Преузимање базе података','Restoring the database'=>'Враћање базе података','Updating the site address'=>'Ажурирање адресе веб места','Switching to the restored database'=>'Пребацивање на враћену базу података','The restore reached an unknown stage.'=>'Враћање је достигло непознату фазу.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Ова фасцикла не садржи потпуну резервну копију Zinn® Backups (манифест недостаје).','This backup is encrypted. Enter its passphrase to restore it.'=>'Ова резервна копија је шифрована. Унесите њену лозинку да бисте је вратили.','This incremental backup needs backup %s, which is no longer in the storage.'=>'За ову инкременталну резервну копију потребна је резервна копија %s, која се више не налази у складишту.','Restoring the backup of %1$s (%2$d file parts).'=>'Враћање резервне копије за %1$s (%2$d делова датотеке).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Датотека %1$s није могла бити преписана јер овом месту није дозвољено да је мења, па је остављена таква каква јесте: %2$s' . "\0" . '%1$s датотека није могло бити преписано јер овом месту није дозвољено да их мења, те су остављене такве какве јесу: %2$s' . "\0" . '%1$s датотека није могло бити преписано јер овом месту није дозвољено да их мења, те су остављене такве какве јесу: %2$s','Restored %s files.'=>'Враћено је %s датотека.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s се не подудара са својом контролном сумом након преузимања. Копија у складишту је можда оштећена.','%s did not arrive. Upload it again.'=>'%s није стигао. Пошаљите га поново.','Recognised: %s.'=>'Препознато: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Увезено је %1$s датотека у wp-content (изостављено је %2$s: кешови, drop-in додаци и фасцикле осталих додатака за резервне копије).','The archive has no database dump, so only files were imported.'=>'Архива нема извоз базе података, па су увезене само датотеке.','Database restored into %d temporary tables.'=>'База података је враћена у %d привремених табела.','%s has no WordPress tables in it and was skipped.'=>'%s не садржи WordPress табеле и прескочен је.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'База података резервне копије нема WordPress табеле, па ништа није замењено.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Ова резервна копија припада мрежи веб-места (multisite). Враћање мреже на једно веб-место није подржано.','Moving the content from %1$s to %2$s.'=>'Премештање садржаја из %1$s у %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Враћање је завршено. Ако сте одјављени, пријавите се налогом са враћеног веб-места.','Restore complete.'=>'Враћање је завршено.','%1$s — trying again in %2$d seconds.'=>'%1$s — поновни покушај за %2$d секунди.','Cancelled.'=>'Отказано.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Резервне копије иду на једно одредиште за складиштење. Уредите или уклоните постојеће да бисте користили друго.','The database file could not be opened.'=>'Датотека базе података није могла бити отворена.','The database refused a statement from the backup: %1$s (%2$s…)'=>'База података је одбила наредбу из резервне копије: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Враћене табеле се нису могле заменити: %s. Ваше веб-место је непромењено.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Не постоји фасцикла са правима уписа за привремене датотеке резервних копија. Омогућите упис у wp-content и покушајте поново.','Could not create a folder for this job.'=>'Није било могуће направити фасциклу за овај задатак.','%s — guides and services'=>'%s — водичи и услуге','User guides'=>'Кориснички водичи','Read the %s user guide'=>'Прочитајте кориснички водич за %s','Hide this'=>'Сакриј ово','Zinn® hosting for WordPress'=>'Zinn® хостинг за WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, свакодневне резервне копије, бесплатна миграција и контролни панел направљен за људе који воде више од једног сајта.','The Zinn® marketplace'=>'Zinn® тржиште','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Купујте и продајте утврђене сајтове, домене и постављања веза, уз сигурно чување новца све док обе стране не буду задовољне.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — ангажујте људе којима је ово посао','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Наше глобално тржиште за хонорарце: прегледајте преко 10.000 готових услуга писаца, дизајнера, програмера и СЕО стручњака, или објавите пројекат и дозволите им да дају понуде.','See the Zinn Digital® release notes.'=>'Погледајте белешке о издању за Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Сервис за ажурирање Zinn® није издао везу за преузимање за ово ажурирање. Проверите да ли ово веб-место може да приступи платформи Zinn®, а затим покушајте поново.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ажурирање није могло бити преузето са Zinn® сервиса за ажурирање (%s). Покушајте поново за неколико минута.','The downloaded update failed its integrity check and was not installed.'=>'Преузето ажурирање није прошло проверу интегритета и није инсталирано.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Zip архива се не може отворити. Можда је оштећена или непотпуна.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Ова .wpress датотека користи формат који не можемо да прочитамо (можда је компримована или шифрована помоћу All-in-One WP Migration). Извезите је поново без шифровања.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Ово је Duplicator „DupArchive“ (.daf) датотека. У додатку Duplicator поново направите пакет са форматом архиве подешеним на ZIP, а затим га увезите.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Ова резервна копија базе података UpdraftPlus је шифрована. Дешифрујте је у UpdraftPlus (или искључите шифровање базе података и поново направите резервну копију), а затим је увезите.','Database dump'=>'Дамп базе података','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s није архива резервне копије коју можемо прочитати (zip, tar, tar.gz, .wpress, .sql или .sql.gz).','Website archive'=>'Архива веб-места','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s не садржи WordPress садржај (нема фасциклу wp-content нити извоз базе података).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ова .wpress датотека је шифрована или компресована помоћу All-in-One WP Migration. Извезите је поново са искљученим шифровањем и компресијом, а затим је увезите.','Other S3-compatible storage'=>'Друго складиште компатибилно са S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 или компатибилно са S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Кључеви за складиштење нису могли бити прочитани на овом сајту. Поново унесите тајни кључ на картици Складиштење.','This kind of storage is not known.'=>'Ова врста складишта није позната.','Choose a kind of storage.'=>'Изаберите врсту складишта.','Enter the bucket name and the access key.'=>'Унесите назив бакета и приступни кључ.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Унесите ID свог Cloudflare налога (или пуну R2 крајњу тачку).','Enter the endpoint address of your storage.'=>'Унесите адресу крајње тачке вашег складишта.','Enter the OAuth client id from your Google Cloud project.'=>'Унесите OAuth client id из свог Google Cloud пројекта.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox није вратио токен за освежавање. Покрените повезивање поново.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox није повезан. Повежите га поново на картици Складиште.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google није вратио жетон за освежавање. Уклоните ово веб-место из приступа трећих страна на свом Google налогу и повежите се поново.','That file is not in Google Drive any more.'=>'Та датотека више није на Google Drive-у.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive није повезан. Повежите га поново на картици Складиште.','The storage service did not start the upload.'=>'Услуга складиштења није покренула отпремање.','The storage service sent a reply that could not be read.'=>'Услуга складиштења је послала одговор који се не може прочитати.','A temporary backup file could not be read.'=>'Није било могуће прочитати привремену датотеку резервне копије.','A deploy link is read-only.'=>'Веза за постављање је само за читање.','The deploy code has no link for a file this backup needs.'=>'Код за постављање нема везу за датотеку која је потребна овој резервној копији.','The deploy link'=>'Веза за постављање']];